#!/usr/bin/env python3
"""Python re-implementation of src/program.cbl (GnuCOBOL BOOKFORUM)."""

from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
INPUT_PATH = BASE_DIR / "src" / "INPUT.DAT"
DATA_DIR = BASE_DIR / "data"
ACCOUNTS_PATH = DATA_DIR / "ACCOUNTS.DAT"
BOOKS_PATH = DATA_DIR / "BOOKS.DAT"
TRANSACTIONS_PATH = DATA_DIR / "TRANSACTIONS.DAT"

ACCOUNT_LEN = 34
BOOK_LEN = 28
TRANSACTION_LEN = 22
INPUT_LEN = 22


def parse_display_number(raw: bytes) -> int:
    """Mimic GnuCOBOL's conversion of an unsigned DISPLAY numeric field.

    The 0xff/0x00 tests reproduce GnuCOBOL's special handling for those
    bytes in the first position.  The rest mirrors its DISPLAY parser:
    leading bytes whose low nibble is zero are skipped, then the remaining
    bytes are accumulated as (byte - ord('0')) digits.  A negative result
    is interpreted as an unsigned 64-bit value by the runtime.
    """
    if raw and raw[0] == 0xFF:
        return 10 ** len(raw)
    if raw and raw[0] == 0x00:
        return -(10 ** len(raw))

    start = 0
    last = len(raw) - 1
    while start < last and (raw[start] & 0x0F) == 0:
        start += 1

    value = 0
    for byte in raw[start:]:
        value = value * 10 + (byte - 0x30)

    if value < 0:
        value %= 1 << 64
    return value


def amount_field_to_ws(amount_field: bytes) -> bytes:
    """MOVE INPUT-AMOUNT (9(10)) TO WS-AMOUNT (9(10)V99)."""
    # GnuCOBOL's display-to-display move maps NUL and space to '0' in
    # place and appends two zero digits for the extra decimal scale.
    mapped = bytes(0x30 if byte in (0x00, 0x20) else byte
                   for byte in amount_field)
    return mapped + b"00"


def trunc_div_100(value: int) -> int:
    if value >= 0:
        return value // 100
    return -((-value) // 100)


def apply_balance_arithmetic(balance: int, ws_amount: int,
                             subtract: bool) -> int:
    """Apply ADD/SUBTRACT to a 10-digit unsigned account balance."""
    if subtract:
        numerator = balance * 100 - ws_amount
    else:
        numerator = balance * 100 + ws_amount

    result = trunc_div_100(numerator)
    # The receiving field is unsigned and has ten digits.
    return abs(result) % (10 ** 10)


def format_balance(balance: int) -> bytes:
    return f"{balance:010d}".encode("ascii")


def read_records(data: bytes, record_len: int):
    """Yield (offset, record) like a fixed-length sequential COBOL READ.

    The COBOL record area is zero-initialised and is reused for each read,
    so a final partial record keeps the unread bytes from the previous read.
    """
    record_area = bytearray(record_len)
    offset = 0
    while offset < len(data):
        chunk = data[offset:offset + record_len]
        record_area[:len(chunk)] = chunk
        yield offset, bytes(record_area)
        offset += record_len


def read_input_record():
    data = INPUT_PATH.read_bytes()
    if not data:
        return None

    record = data[:INPUT_LEN]
    if len(record) < INPUT_LEN:
        record += b"\x00" * (INPUT_LEN - len(record))
    return record


def validate(buyer_id: bytes, seller_id: bytes, book_id: bytes):
    buyer_found = False
    seller_found = False
    book_found = False
    valid_owner = False

    accounts_data = ACCOUNTS_PATH.read_bytes()
    for _, record in read_records(accounts_data, ACCOUNT_LEN):
        account_id = record[0:4]
        if account_id == buyer_id:
            buyer_found = True
        if account_id == seller_id:
            seller_found = True

    books_data = BOOKS_PATH.read_bytes()
    for _, record in read_records(books_data, BOOK_LEN):
        if record[0:4] == book_id:
            book_found = True
            if record[24:28] == seller_id:
                valid_owner = True

    return buyer_found, seller_found, book_found, valid_owner


def process_accounts(buyer_id: bytes, seller_id: bytes,
                     ws_amount: int) -> bytes:
    data = ACCOUNTS_PATH.read_bytes()
    output = bytearray(data)

    for offset, record in read_records(data, ACCOUNT_LEN):
        balance = parse_display_number(record[24:34])
        changed = False

        if record[0:4] == buyer_id:
            balance = apply_balance_arithmetic(balance, ws_amount, True)
            changed = True
        if record[0:4] == seller_id:
            balance = apply_balance_arithmetic(balance, ws_amount, False)
            changed = True

        if changed:
            new_record = record[0:24] + format_balance(balance)
            output[offset:offset + ACCOUNT_LEN] = new_record

    return bytes(output)


def process_books(book_id: bytes, buyer_id: bytes) -> bytes:
    data = BOOKS_PATH.read_bytes()
    output = bytearray(data)

    for offset, record in read_records(data, BOOK_LEN):
        if record[0:4] == book_id:
            new_record = record[0:24] + buyer_id + record[28:BOOK_LEN]
            output[offset:offset + BOOK_LEN] = new_record

    return bytes(output)


def main():
    input_record = read_input_record()
    if input_record is None:
        print("Error: Input file is empty")
        return

    buyer_id = input_record[0:4]
    seller_id = input_record[4:8]
    book_id = input_record[8:12]
    amount_field = input_record[12:22]

    ws_amount_bytes = amount_field_to_ws(amount_field)
    ws_amount = parse_display_number(ws_amount_bytes)

    buyer_found, seller_found, book_found, valid_owner = validate(
        buyer_id, seller_id, book_id
    )

    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        return

    accounts_output = process_accounts(buyer_id, seller_id, ws_amount)
    books_output = process_books(book_id, buyer_id)

    # MOVE WS-AMOUNT (scale 2) TO TRANS-AMOUNT (scale 0) keeps the first
    # ten bytes of the display representation.  This is the mapped input
    # amount field.
    transaction_amount = ws_amount_bytes[0:10]
    transaction_record = (
        book_id + transaction_amount + seller_id + buyer_id
    )

    ACCOUNTS_PATH.write_bytes(accounts_output)
    BOOKS_PATH.write_bytes(books_output)
    with TRANSACTIONS_PATH.open("ab") as transactions_file:
        transactions_file.write(transaction_record)

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()

